import{c as s,Q as a,j as t,m as i}from"./chunks/framework.BXc4yaFE.js";const k=JSON.parse('{"title":"How to optimize your Claude setup to get the most out of Fable","description":"","frontmatter":{"url":"https://x.com/ksimback/status/2072752017186107866","title":"How to optimize your Claude setup to get the most out of Fable","author":"KSimback","archived":"2026-07-03T00:00:00.000Z","handle":"@KSimback","published":"2026-07-02T00:00:00.000Z","stats":"88 likes · 2 retweets · 140 bookmarks · 17053 views","tags":["fable5","model-routing","token-optimization","CLAUDE-md","plugin-management","effort"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-02-@KSimback-107866.md","filePath":"research/tweets/2026-07-02-@KSimback-107866.md","lastUpdated":1785909234000}'),n={name:"research/tweets/2026-07-02-@KSimback-107866.md"};function o(l,e,r,d,p,h){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="how-to-optimize-your-claude-setup-to-get-the-most-out-of-fable-—-ksimback" tabindex="-1">How to optimize your Claude setup to get the most out of Fable — @KSimback <a class="header-anchor" href="#how-to-optimize-your-claude-setup-to-get-the-most-out-of-fable-—-ksimback" aria-label="Permalink to &quot;How to optimize your Claude setup to get the most out of Fable — @KSimback&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/ksimback/status/2072752017186107866" target="_blank" rel="noreferrer">https://x.com/ksimback/status/2072752017186107866</a><strong>作者</strong>：KSimback（@KSimback） <strong>發布日期</strong>：2026-07-02 <strong>收錄日期</strong>：2026-07-03 <strong>類型</strong>：Twitter Article <strong>統計</strong>：88 likes · 2 retweets · 140 bookmarks · 17053 views</p><hr><h2 id="全文-核心技術段落" tabindex="-1">全文（核心技術段落） <a class="header-anchor" href="#全文-核心技術段落" aria-label="Permalink to &quot;全文（核心技術段落）&quot;">​</a></h2><p><strong>定位</strong>：Fable = senior engineer，規劃/決策/調試硬問題/審查；<strong>絕不</strong>做 grep、boilerplate、browser automation 的 volume work。</p><h3 id="phase-1-—-assessment-prompt" tabindex="-1">Phase 1 — Assessment Prompt <a class="header-anchor" href="#phase-1-—-assessment-prompt" aria-label="Permalink to &quot;Phase 1 — Assessment Prompt&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Inspect my current setup and report where I stand on each recommendation:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Read ~/.claude/settings.json: note my model, effortLevel, globally enabled plugins.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Read ~/.claude/CLAUDE.md: do I have model-routing or subagent delegation rules?</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Check ~/.claude/agents/: any agent definitions with pinned models?</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Check for external code CLI (e.g. codex on PATH) or skills wrapping one.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Present as short table: recommendation / current state / already done/partial/not done.</span></span></code></pre></div><h3 id="_7-具體建議" tabindex="-1">7 具體建議 <a class="header-anchor" href="#_7-具體建議" aria-label="Permalink to &quot;7 具體建議&quot;">​</a></h3><p><strong>1. 在 CLAUDE.md 增加 model-routing 段落</strong></p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Model &amp; Token Routing</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Fable (main loop) is for: architecture, planning, hard debugging, final</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">review/synthesis, and anything ambiguous. Everything else gets delegated</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">to cheaper models.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">When spawning subagents (Agent tool) or workflow agents, set the model explicitly:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **sonnet**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (default for all exploration and analysis): file/code search,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  exploration fan-outs, codebase analysis, log scanning, data extraction,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  standard implementation from a clear spec, QA runs, doc updates.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ⚠️ Do NOT use haiku for exploration — a subtly wrong exploration summary</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  taken as given by Fable costs more than the tokens saved.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **opus**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: complex implementation, code review passes, tricky refactors</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **omit model (inherit Fable)**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: only for design decisions, adversarial</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  verification of critical findings, or synthesis across many agent results</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Effort: use &quot;low&quot; for mechanical stages, session default for normal work,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;high&quot;+ only for verify/judge/design stages.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Subagents must return conclusions with file:line references — never raw file</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">contents or dumps.</span></span></code></pre></div><p><strong>2. 不要默認跑 1M context 變體</strong><code>claude-fable-5[1m]</code> → 改回 <code>claude-fable-5</code>（除非日常需要整 codebase 在一個 session）。每次 turn 重讀累積上下文，1M 讓 session 累積遠多於必要。</p><p><strong>3. 重型 plugin 按 project 啟用，不全局</strong> 每個 project 的 <code>.claude/settings.json</code> 啟用，而非 <code>~/.claude/settings.json</code>。每個 enabled plugin 的 skill/agent 描述每次 session 開始都載入上下文，對不使用的 session 是純 overhead。</p><p><strong>4. 探索任務強制用 model override</strong> 在 <code>~/.claude/agents/</code> 建 <code>explorer.md</code>（前端設 <code>model: sonnet</code>），不依賴 orchestrator 記住。</p><p><strong>5. Subagent 返回 evidence（file:line）而非 dump</strong> 節省兩次：(1) Fable 不用重讀便宜模型已讀的內容；(2) 讓探索可 spot-check，Fable 只需讀 5 行驗證。</p><p><strong>6. 大型實作委派給外部 CLI（Codex）</strong> Fable 寫緊湊 spec → 外部 CLI 執行 → Fable review diff。保留判斷兩端，省掉 volume 中段。</p><p><strong>7. 分層 effort，不要全 max</strong> 中等 session 默認（medium/high），最難的 verify/judge/design 才用 xhigh（per-agent override），max 是單一難問題工具，不是吞吐量工具。</p><p><strong>Bonus</strong>：Browser automation 用 headless-browser skill，不用 screenshot computer use（極度 token-heavy）。</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：7 條具體 Claude setup 優化建議，核心是把 Fable 定位為高判斷力的 orchestrator/reviewer，exploration/implementation volume work 全交給便宜模型；關鍵洞察：Haiku 做 exploration 的「靜默錯誤」成本比省下的 token 更貴。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>⚠️ 勿用 Haiku 做 exploration</strong>：細微錯誤的 exploration summary 被 Fable 當真後放大，成本遠超省下的 token</li><li><code>claude-fable-5[1m]</code> 不是默認最優（session 累積上下文代價）</li><li>Plugin 只按 project 啟用（每個 plugin 的 skill 描述都是 context overhead）</li><li>Fork subagents 永遠繼承主循環模型（不受 model override 控制）</li><li>Browser screenshot computer use 是最貴的 token 模態</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>CLAUDE.md Model Routing 模板（含 sonnet/opus/Fable 分工）</li><li><code>~/.claude/agents/explorer.md</code>（pinned sonnet in frontmatter）</li><li><code>effortLevel</code> 分層：medium/high default；xhigh per-agent override</li><li><code>claude-fable-5</code> vs <code>claude-fable-5[1m]</code> 的成本差異</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>Haiku 禁 exploration 洞察是本文最值得加進 delegation-protocol 的發現</li><li>文章直接提供 CLAUDE.md 片段，可直接 copy-paste（高可行動性）</li><li>無定量成本數據，但機制解釋清晰</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>CLAUDE.md snippet 直接可用；7條規則對應 workspace 現有 delegation-protocol</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>Haiku exploration 靜默失敗洞察是新的；其餘是已知原則的具體化</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>機制解釋清晰但無定量數據；Phase 1 assessment prompt 設計良好</td></tr><tr><td>D. 技術深度 (15%)</td><td>8/10</td><td>Fork subagent 繼承特性、1M 上下文複利問題、effort multiplier 有深度</td></tr><tr><td>E. 泛化性 (15%)</td><td>7.5/10</td><td>Claude Code 特定但原則（exploration floor）跨模型通用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.8/10</strong></td><td>9×0.3+7×0.2+7×0.2+8×0.15+7.5×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：Haiku 禁 exploration 規則需補進 delegation-protocol.md；CLAUDE.md Model Routing 模板可更新現有 model-selection-grid；plugin 按 project 啟用規則可加進 maintenance-protocol.md。</p>`,30)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
